import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { ToastContainer, toast } from 'react-toastify';
import { motion } from 'framer-motion';
import 'react-toastify/dist/ReactToastify.css';
import './App.css';

function App() {
  const [posts, setPosts] = useState([]);
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [image, setImage] = useState(null);
  const [imagePreview, setImagePreview] = useState('');
  const [editId, setEditId] = useState(null);

  const fetchPosts = async () => {
    const res = await axios.get('http://localhost:5000/posts');
    setPosts(res.data);
  };

  const handleSubmit = async () => {
    if (!title || !content) return;

    const formData = new FormData();
    formData.append('title', title);
    formData.append('content', content);
    if (image) formData.append('image', image);

    try {
      if (editId) {
        await axios.put(`http://localhost:5000/posts/${editId}`, formData);
        toast.info('Post updated!');
        setEditId(null);
      } else {
        await axios.post('http://localhost:5000/posts', formData);
        toast.success('Post created!');
      }
      setTitle('');
      setContent('');
      setImage(null);
      setImagePreview('');
      fetchPosts();
    } catch {
      toast.error('Error occurred!');
    }
  };

  const handleEdit = (post) => {
    setEditId(post._id);
    setTitle(post.title);
    setContent(post.content);
    setImagePreview(post.image || '');
  };

  const handleDelete = async (id) => {
    await axios.delete(`http://localhost:5000/posts/${id}`);
    toast.error('Post deleted!');
    fetchPosts();
  };

  useEffect(() => {
    fetchPosts();
  }, []);

  return (
    <>
      <header className="header">My Modern Blog</header>
      <main className="container">
        <div className="form-box">
          <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Title" />
          <textarea value={content} onChange={(e) => setContent(e.target.value)} placeholder="Content" />
          <input
            type="file"
            onChange={(e) => {
              setImage(e.target.files[0]);
              setImagePreview(URL.createObjectURL(e.target.files[0]));
            }}
          />
          {imagePreview && (
            <div className="image-card">
              <img src={imagePreview} alt="preview" />
            </div>
          )}
          <button onClick={handleSubmit}>{editId ? 'Update Post' : 'Create Post'}</button>
        </div>

        <div className="posts">
          {posts.map((post) => (
            <motion.div
              key={post._id}
              className="post"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3 }}
            >
              <h3>{post.title}</h3>
              <p>{post.content}</p>
              {post.image && <img src={post.image} alt="post" className="post-img" />}
              <div className="btn-group">
                <button onClick={() => handleEdit(post)}>Edit</button>
                <button onClick={() => handleDelete(post._id)}>Delete</button>
              </div>
            </motion.div>
          ))}
        </div>
      </main>
      <footer className="footer">&copy; 2025 Blog Platform. All rights reserved.</footer>
      <ToastContainer position="bottom-right" autoClose={2000} />
    </>
  );
}

export default App;
